.xdsoft_datetimepicker {
 box-shadow: 0 5px 15px -5px rgba(0, 0, 0, 0.506);
 background: #fff;
 border-bottom: 1px solid #bbb;
 border-left: 1px solid #ccc;
 border-right: 1px solid #ccc;
 border-top: 1px solid #ccc;
 color: #333;
 font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
 padding: 8px;
 padding-left: 0;
 padding-top: 2px;
 position: absolute;
 z-index: 9999;
 -moz-box-sizing: border-box;
 box-sizing: border-box;
 display: none;
}
.xdsoft_datetimepicker.xdsoft_rtl {
 padding: 8px 0 8px 8px;
}

.xdsoft_datetimepicker iframe {
 position: absolute;
 left: 0;
 top: 0;
 width: 75px;
 height: 210px;
 background: transparent;
 border: none;
}

/*For IE8 or lower*/
.xdsoft_datetimepicker button {
 border: none !important;
}

.xdsoft_noselect {
 -webkit-touch-callout: none;
 -webkit-user-select: none;
 -khtml-user-select: none;
 -moz-user-select: none;
 -ms-user-select: none;
 -o-user-select: none;
 user-select: none;
}

.xdsoft_noselect::selection { background: transparent }
.xdsoft_noselect::-moz-selection { background: transparent }

.xdsoft_datetimepicker.xdsoft_inline {
 display: inline-block;
 position: static;
 box-shadow: none;
}

.xdsoft_datetimepicker * {
 -moz-box-sizing: border-box;
 box-sizing: border-box;
 padding: 0;
 margin: 0;
}

.xdsoft_datetimepicker .xdsoft_datepicker, .xdsoft_datetimepicker .xdsoft_timepicker {
 display: none;
}

.xdsoft_datetimepicker .xdsoft_datepicker.active, .xdsoft_datetimepicker .xdsoft_timepicker.active {
 display: block

/* 本页 */

.contain {
 width: 1200px;
 height: 832px;
 margin: 16px auto;
}

.newColumn .procurementAnnouncementList {
 width: 288px;
 margin-right: 16px;
 height: 100%;
 background-color: #fff;
}

.procurementAnnouncementList .title {
 width: 288px;
 height: 64px;
 margin: 10px 0px 8px;
 position: relative;
}

.procurementAnnouncementList .title .name {
 display: inline-block;
 background: #fff;
 position: relative;
 /* width: 170px; */
 height: 60px;
 font-size: 20px;
 line-height: 60px;
 margin-left: 36px;
 padding: 0px 5px;
 font-weight: bold;
}

.procurementAnnouncementList .title:before {
 content: '';
 display: block;
 height: 10px;
 width: 256px;
 /*background-color: #DB3B40;*/
 background-color: #2461b1;
 position: relative;
 top: 35px;
 left: 16px;
}

.noticeList li {
 width: 256px;
 height: 40px;
 background-color: #fff;
 color: #000;
 /*margin: 12px 16px;*/
 line-height: 40px;
 font-size: 14px;
 cursor: pointer;
}

.noticeList .iconfont {
 vertical-align: middle;
 margin: 0px 10px;
 line-height: 40px;
 font-size: 20px;
}

/*.actived {*/
/* background-color: #DB3B40 !important;*/
/* color: #fff !important;*/
/*}*/

.newColumn .procurementAnnouncementContent {
 width: 896px;
 /*height: 100%;*/
 /*background-color: #fff;*/
}

.searchBox {
 width: 896px;
 padding: 40px 16px 32px 16px;
 /*height: 164px;*/
}

.procurementAnnouncementSearch-row {
 margin-bottom: 24px;
}

.procurementAnnouncementSearch-item {
 display: inline-block;

}

.procurementAnnouncementSearch label

(function ($) {
 $.fn.floatAd = function (options) {
 var defaults = {
 speed: 10 //漂浮速度 单位毫秒
 };
 var options = $.extend(defaults, options);
 var obj = $(this);
 obj.css('position', 'fixed');
 function init() {
 var x = 0,
 y = 0,
 xin = true,
 yin = true,
 step = 1;
 var float = function () {
 var L = T = 0,
 OW = obj.width(), //当前广告的宽
 OH = obj.height(), //高
 DW = $(window).width(), //浏览器窗口的宽
 DH = $(window).height();

 x = x + step * (xin ? 1 : -1);
 if (x < L) {
 xin = true;
 x = L;
 }
 if (x > DW - OW - 1) { //-1为了ie
 xin = false;
 x = DW - OW - 1;
 }

 y = y + step * (yin ? 1 : -1);
 if (y > DH - OH - 1) {

 yin = false;
 y = DH - OH - 1;
 }
 if (y < T) {
 yin = true;
 y = T;
 }

 var left = x;
 var top = y;

 obj.css({
 'top': top,
 'left': left
 });
 }
 var itl = setInterval(float, options.speed);
 obj.mouseover(function () {
 clearInterval(itl)
 });
 obj.mouseout(function () {
 itl = setInterval(float, options.speed)
 })
 }

 init();

 }; //autoMove

})(jQuery);

(function($){
 var cookieExpireTime = 1209600; // cookie项过期时间 2周
 $.session = {
 _id: null,

 _cookieCache: undefined,

 _init: function()
 {
 //if (!window.name) {
 // window.name = Math.random();
 //}
 //this._id = window.name;
 // 如果id设置为动态，会导致浏览器不断生成cookie，进而导致取值有问题
 this._id = 'sessionID';
 this._initCache();

 // See if we've changed protcols
 var matches = (new RegExp(this._generatePrefix() + "=([^;]+);")).exec(document.cookie);
 if (matches && document.location.protocol !== matches[1]) {
 this._clearSession();
 for (var key in this._cookieCache) {
 try {
 window.sessionStorage.setItem(key, this._cookieCache[key]);
 } catch (e) {};
 }
 }

 document.cookie = this._generatePrefix() + "=" + document.location.protocol + ';path=/;expires=' + (new Date((new Date).getTime() + 28800000 + cookieExpireTime)).toUTCString(); // 28800000 含义：世界时间+8天=北京时间

 },

 _generatePrefix: function()
 {
 return '__session:' + this._id + ':';
 },

 _initCache: function()
 {
 var cookies = document.cookie.split(';');
 this._cookieCache = {};
 for (var i in cookies) {
 var kv = cookies[i].split('=');
 if ((new RegExp(this._generatePrefix() + '.+')).test(kv[0]) && kv[1]) {
 this._cookieCache[kv[0].split(':', 3)[2]] = kv[1];
 }
 }
 },

 _setFallback: function(key, value, onceOnly)
 {
 var cookie = this._generatePrefix() + key + "=" + value + ";path=/";
 if (onceOnly) { // 只一次设置项，为其添加过期时间，过期自动删除
 cookie += ";expires=" + (new Date(Date.now() + 28800000 + cookieExpireTime)).toUTCString();
 }
 document.

.pagination ul {
 list-style: none;
 padding-left: 0;
}

.pagination ul li {
 padding: 0 10px;
 vertical-align: top;
 display: inline-block;
 font-size: 14px;
 min-width: 36px;
 min-height: 28px;
 line-height: 28px;
 cursor: pointer;
 box-sizing: border-box;
 text-align: center;
 background-color: #ffffff;
 color: #606266;
 border-radius: 6px;
 margin: 0 1px;
 border: 1px solid #ebebeb;
 height: 30px;
}

/*.pagination ul li:hover {*/
/* transform: scale(1.1);*/
/* background-color: #F4F6F8;*/
/*}*/

.pagination li.active {
 /*background: #DB3B40;*/
 background: #2461b1;
 color: white;
 cursor: not-allowed;
}

.pagination li.disabled {
 cursor: not-allowed;
}
.pagination li.totalPage {
 background: transparent;
 cursor: default;
 border: none;
 padding: 0 6px;
}

.pagination li.totalPage:hover {
 transform: none;
 background-color: #ffffff;
}

.pagination li input {
 -webkit-appearance: none;
 background-color: #fff;
 background-image: none;
 border-radius: 4px;
 border: 1px solid #dcdfe6;
 box-sizing: border-box;
 color: #606266;
 display: inline-block;
 font-size: inherit;
 outline: none;
 padding: 3px 5px;
 transition: border-color .2s cubic-bezier(.645,.045,.355,1);
 width: 40px;
 height: 25px;
 margin: 0 6px;
}

.pagination li input:focus{
 border-color: #98A6AD;
}
.pagination{
 user-select: none;
}

.pagination ul:nth-child(2){
 border-radius: 6px;
}

input[type=number] {
 -moz-appearance:textfield;
}
input[type=number]::-webkit-inner-spin-button,
input[type=number]::-we

.lay-ext-mulitsel .layui-form-select dl dd div {
 margin-top: 0px !important;
}

.lay-ext-mulitsel .layui-input.multiple {
 display: flex;
 flex-wrap: wrap;
 align-items: center;
 line-height: auto;
 height: auto;
 overflow: hidden;
 height: 41px;
 z-index: 99;
 background: #fff;
 width: 300px;
 transform: translateY(-35px);
}

 .lay-ext-mulitsel .layui-input.multiple a {
 padding: 0px 5px;
 background: #0059BF;
 border-radius: 2px;
 color: #fff;
 display: block;
 font-size: 12px;
 line-height: 16px;
 height: 16px;
 margin: 2px 5px 2px 0;
 float: left;
 }

 .lay-ext-mulitsel .layui-input.multiple a i {
 margin-left: 4px;
 font-size: 12px;
 }

 .lay-ext-mulitsel .layui-input.multiple a i:hover {
 background-color: #009E94;
 border-radius: 2px;
 }

.lay-ext-mulitsel .danger {
 border-color: #FF5722 !important
}

.lay-ext-mulitsel .tips {
 pointer-events: none;
 position: absolute;
 left: 10px;
 top: 10px;
 color: #757575;
}

